// Package postgres is the challenge module's Repo on the platform database (queries.sql, generated by sqlc).
package postgres

import (
	"context"
	"database/sql"
	"encoding/json"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/challenge"
)

// Repo implements challenge.Repo.
type Repo struct {
	q *Queries
}

var _ challenge.Repo = (*Repo)(nil)

// NewRepo uses the open database db.
func NewRepo(db *sql.DB) *Repo { return &Repo{q: New(db)} }

// Create stores a judged submission and returns its id.
func (r *Repo) Create(ctx context.Context, s challenge.Submission) (int64, error) {
	result, err := json.Marshal(s.Result)
	if err != nil {
		return 0, err
	}
	return r.q.InsertSubmission(ctx, InsertSubmissionParams{UserID: s.UserID, CourseID: s.Course, ItemID: s.Item,
		ContentHash: s.Hash, Language: s.Language, Code: s.Code, Verdict: s.Verdict, Passed: int64(s.Passed),
		Total: int64(s.Total), Seconds: s.Seconds, Xp: int64(s.XP), Result: result, SubmittedAt: s.SubmittedAt})
}

// Submissions are user's submissions to an item, newest first.
func (r *Repo) Submissions(ctx context.Context, user int64, course, item string) ([]challenge.Submission, error) {
	rows, err := r.q.ItemSubmissions(ctx, ItemSubmissionsParams{UserID: user, CourseID: course, ItemID: item})
	if err != nil {
		return nil, err
	}
	return submissions(rows)
}

// Accepted are user's accepted submissions, oldest first.
func (r *Repo) Accepted(ctx context.Context, user int64) ([]challenge.Submission, error) {
	rows, err := r.q.AcceptedSubmissions(ctx, user)
	if err != nil {
		return nil, err
	}
	return submissions(rows)
}

func submissions(rows []ChallengeSubmission) ([]challenge.Submission, error) {
	out := make([]challenge.Submission, len(rows))
	for i, row := range rows {
		out[i] = challenge.Submission{ID: row.ID, UserID: row.UserID, Course: row.CourseID, Item: row.ItemID,
			Hash: row.ContentHash, Language: row.Language, Code: row.Code, Verdict: row.Verdict,
			Passed: int(row.Passed), Total: int(row.Total), Seconds: row.Seconds, XP: int(row.Xp),
			SubmittedAt: row.SubmittedAt}
		if err := json.Unmarshal(row.Result, &out[i].Result); err != nil {
			return nil, err
		}
	}
	return out, nil
}
